// Formats the failure as one line and appends it to the mock outbox. Error messages can echo
// request data, so anything that looks like an email address is redacted and the text is capped.
const fs = require('fs');

const oneLine = (value, max) => String(value == null ? '' : value).replace(/\s+/g, ' ').trim().slice(0, max);
const redact = (text) => text.replace(/[^\s@"'<>]+@[^\s@"'<>]+/g, '[redacted-email]');

const data = $input.first().json;
// A failing trigger node reports under "trigger" and has no execution yet.
const execution = data.execution || {};
const failure = execution.error || (data.trigger && data.trigger.error) || {};

const alert = {
  at: new Date().toISOString(),
  channel: 'error-handler',
  workflow: oneLine(data.workflow && data.workflow.name, 120),
  node: oneLine((failure.node && failure.node.name) || execution.lastNodeExecuted || 'unknown', 120),
  error: redact(oneLine(failure.message || failure.description || 'unknown error', 500)),
  executionId: execution.id || null,
  executionUrl: execution.url || null,
};
alert.text =
  'LendLoop n8n failure: workflow "' + alert.workflow + '", node "' + alert.node + '": ' + alert.error +
  (alert.executionId ? ' (execution ' + alert.executionId + (alert.executionUrl ? ', ' + alert.executionUrl : '') + ')' : '');

const outbox = $env.LENDLOOP_MOCK_OUTBOX;
if (outbox) fs.appendFileSync(outbox, JSON.stringify(alert) + '\n');
return [{ json: alert }];
